    // ];
    // 95% Confidence Interval, constrained within [0, 100]
    const CI = [
      Math.max(0, Math.min((proportionKnown - 1.96 * SE) * 100, 100)),
      Math.max(0, Math.min((proportionKnown + 1.96 * SE) * 100, 100))
    ];

    // setStandardError(SE.toFixed(3));
