//code 7 works fro chrome but not for android phone in other than english or iphones
'use client';

import { useEffect, useState } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import Papa from 'papaparse';
import { FiRefreshCw } from 'react-icons/fi';

export default function VocabQuiz() {
  const router = useRouter();
  const params = useSearchParams();
  const storyId = params.get('story');
  const lang = (params.get('lang') || 'EN').toUpperCase();

  const [vocab, setVocab] = useState([]);
  const [stories, setStories] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loaded, setLoaded] = useState(false);
  const [wordOptions, setWordOptions] = useState([]);
  const [highlightIndex, setHighlightIndex] = useState(null);
  const [highlightColor, setHighlightColor] = useState(null);
  const [quizFinished, setQuizFinished] = useState(false);

  const langMap = { EN: 'en', PT: 'pt', ES: 'es', IT: 'it', FR: 'fr', DE: 'de', JA: 'ja' };

  const normalize = (str) =>
    str.replace(/[–—]/g, '-').replace(/[“”]/g, '"').trim();

  /* SMART VOCAB AUDIO (M4A + Better TTS Voice) */
  const playVocabularyAudio = async (text, langCode) => {
    const folder = langCode.toLowerCase();
    const safe = text
      .toLowerCase()
      .replaceAll(" ", "_")
      .replaceAll("'", "")
      .replaceAll('"', "")
      .replaceAll("-", "_");

    // FIX 1 — change opus → m4a
    const soundPath = `/actionSounds/${folder}/${safe}.m4a`;

    try {
      const head = await fetch(soundPath, { method: "HEAD" });
      if (head.ok) {
        new Audio(soundPath).play();
        return;
      }
    } catch (err) {}

    // FIX 2 — better TTS English voice
    try {
      const utter = new SpeechSynthesisUtterance(text);
      utter.lang = folder;

      if (folder === "en") {
        const voices = speechSynthesis.getVoices();
        const naturalVoice =
          voices.find(v =>
            /Google US English|Microsoft (Aria|Guy)|Google UK English/.test(v.name)
          ) || voices.find(v => v.lang.startsWith("en"));

        if (naturalVoice) utter.voice = naturalVoice;
        utter.rate = 0.9;
      }

      window.speechSynthesis.speak(utter);
    } catch (err) {}
  };

  const playImageAudio = () => {
    const word = vocab[currentIndex][langMap[lang]] || vocab[currentIndex].en;
    playVocabularyAudio(word, langMap[lang]);
  };

  /* LOAD CSVs */
  useEffect(() => {
    Promise.all([
      fetch('/actionCSV/VocabularyCSV.csv').then(res => res.text()),
      fetch('/actionCSV/TitlesCSV.csv').then(res => res.text())
    ]).then(([vocabText, titlesText]) => {
      const parsedVocab = Papa.parse(vocabText, {
        header: true,
        skipEmptyLines: true,
        transformHeader: h => h.trim().toLowerCase()
      }).data;

      const parsedStories = Papa.parse(titlesText, {
        header: true,
        skipEmptyLines: true,
        transformHeader: h => h.trim().toLowerCase()
      }).data;

      const storyVocab = parsedVocab.filter(
        v => v.story == storyId && v.file && v.en
      );

      setVocab(storyVocab);
      setStories(parsedStories);
      setLoaded(true);
    });
  }, [storyId]);

  /* SET WORD OPTIONS */
  useEffect(() => {
    if (!loaded || !vocab.length) return;

    const currentWord = vocab[currentIndex];
    const otherWords = vocab
      .filter((_, i) => i !== currentIndex)
      .map(v => v[langMap[lang]] || v.en);

    const shuffledOthers = shuffleArray(otherWords).slice(0, 8);
    const correctWord = currentWord[langMap[lang]] || currentWord.en;

    setWordOptions(shuffleArray([...shuffledOthers, correctWord]));
    setHighlightIndex(null);
    setHighlightColor(null);
  }, [currentIndex, loaded, vocab, lang]);

  const shuffleArray = (arr) => [...arr].sort(() => Math.random() - 0.5);

  const handleBack = () =>
    router.push(`/blogs/blog5/StorySelector`);

  const goToFullStory = () =>
    router.push(`/blogs/blog5/FullStory?story=${storyId}&lang=${lang}`);

  const resetQuiz = () => {
    setCurrentIndex(0);
    setQuizFinished(false);
  };

  /* WORD CLICK */
  const handleWordClick = (word, index) => {
    if (quizFinished) return;

    const correctWord =
      vocab[currentIndex][langMap[lang]] || vocab[currentIndex].en;

    setHighlightIndex(index);
    setHighlightColor(word === correctWord ? 'green' : 'red');

    playVocabularyAudio(word, langMap[lang]);

    setTimeout(() => {
      if (word === correctWord) {
        if (currentIndex < vocab.length - 1)
          setCurrentIndex(prev => prev + 1);
        else
          setQuizFinished(true);
      } else {
        const otherWords = vocab
          .filter((_, i) => i !== currentIndex)
          .map(v => v[langMap[lang]] || v.en);

        const shuffledOthers = shuffleArray(otherWords).slice(0, 8);
        const correctWordFinal = correctWord;

        setWordOptions(
          shuffleArray([...shuffledOthers, correctWordFinal])
        );
        setHighlightIndex(null);
        setHighlightColor(null);
      }
    }, 300);
  };

  if (!loaded || !vocab.length)
    return (
      <p style={{ textAlign: 'center', marginTop: '50px' }}>
        Loading...
      </p>
    );

  const currentVocab = vocab[currentIndex];
  const folderEntry = stories.find(s => s.story == storyId);
  const folderName = `${storyId}. ${folderEntry?.en?.trim() || 'Story'}`;
  const encodedFolderName = encodeURIComponent(folderName);
  const fileIndex = currentVocab.file;
  const safeEnTitle = normalize(currentVocab.en).replace(/\.+$/, '');
  const fileName = `${fileIndex}. ${safeEnTitle}.jpg`;
  const encodedFileName = encodeURIComponent(fileName);
  const imagePath = `/ActionStoriesPics/VocabPics/${encodedFolderName}/${encodedFileName}`;

  return (
    <div
      style={{
        minHeight: '100vh',
        backgroundColor: '#faf7e8',
        padding: '20px',
        textAlign: 'center',
        position: 'relative'
      }}
    >
      {/* Restart icon */}
      <div
        onClick={resetQuiz}
        style={{
          cursor: 'pointer',
          fontSize: '32px',
          color: '#f3c200',
          position: 'absolute',
          top: '20px',
          right: '20px'
        }}
        title="Restart Quiz"
      >
        <FiRefreshCw />
      </div>

      <div
        onClick={handleBack}
        style={{
          cursor: 'pointer',
          fontSize: '16px',
          display: 'flex',
          alignItems: 'center',
          gap: '5px',
          color: '#333',
          fontWeight: '500',
          marginBottom: '20px',
          justifyContent: 'center'
        }}
      >
        ← Back to Story Selection
      </div>

      <div
        style={{
          display: 'flex',
          justifyContent: 'center',
          gap: '40px',
          flexWrap: 'wrap',
          alignItems: 'center',
          flexDirection: typeof window !== "undefined" && window.innerWidth <= 600
            ? 'column'
            : 'row'
        }}
      >

        {/* IMAGE with click-to-play */}
        <img
          src={imagePath}
          onClick={playImageAudio}
          alt={currentVocab[langMap[lang]] || currentVocab.en}
          style={{
            width: '400px',
            height: '300px',
            objectFit: 'contain',
            borderRadius: '12px',
            boxShadow: '0 6px 16px rgba(0,0,0,0.25)',
            cursor: 'pointer'
          }}
        />

        {/* ANSWER GRID */}
        <div
          style={{
            display: 'grid',
            gridTemplateColumns:
              typeof window !== "undefined" && window.innerWidth <= 600
                ? 'repeat(2, 1fr)'
                : 'repeat(3, 1fr)',
            gap: '12px',
            width: '100%',
            maxWidth: '420px',
            alignSelf: 'center',
            justifyItems: 'center',
            alignItems: 'center'
          }}
        >
          {wordOptions.map((word, i) => (
            <div
              key={i}
              onClick={() => handleWordClick(word, i)}
              style={{
                width:
                  typeof window !== "undefined" && window.innerWidth <= 600
                    ? '100px'
                    : '140px',
                height:
                  typeof window !== "undefined" && window.innerWidth <= 600
                    ? '80px'
                    : '100px',
                padding: '8px',
                backgroundColor:
                  highlightIndex === i ? highlightColor : '#fff',
                borderRadius: '10px',
                boxShadow: '0 2px 6px rgba(0,0,0,0.2)',
                textAlign: 'center',
                cursor: quizFinished ? 'not-allowed' : 'pointer',
                fontWeight: '500',
                userSelect: 'none',
                transition: 'background-color 0.2s ease',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                whiteSpace: 'normal',
                wordBreak: 'break-word',
                overflowWrap: 'break-word'
              }}
            >
              {word}
            </div>
          ))}
        </div>
      </div>

      {/* Show Full Story button */}
      <div style={{ marginTop: '80px' }}>
        {quizFinished && (
          <button
            onClick={goToFullStory}
            style={{
              padding: '12px 24px',
              fontSize: '16px',
              fontWeight: '600',
              backgroundColor: '#f3c200',
              border: 'none',
              borderRadius: '8px',
              cursor: 'pointer',
              boxShadow: '0 4px 8px rgba(0,0,0,0.2)'
            }}
          >
            Go to Full Story →
          </button>
        )}
      </div>
    </div>
  );
}

