"use client";

import { useState, useEffect } from "react";
import VideoPlayer from "./VideoPlayer";

export default function Page() {
  const [sections, setSections] = useState([]);
  const [selectedIndex, setSelectedIndex] = useState(0); // default first section

  // Load sections JSON
  useEffect(() => {
    async function loadSections() {
      try {
        const res = await fetch("/thekid/pdfText/sections.json");
        const data = await res.json();
        setSections(data.sections || []);
        console.log("Sections loaded:", data.sections?.length || 0);
      } catch (err) {
        console.error("Failed to load sections JSON:", err);
      }
    }
    loadSections();
  }, []);

  // Get audio URL for a section
  const getAudioUrl = (sectionNumber) => `/thekid/sounds/${sectionNumber}.m4a`;

  return (
    <div
      style={{
        width: "100%",
        minHeight: "100vh",
        padding: "20px",
        background: "#ffffffff",
        color: "white",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: "30px",
        boxSizing: "border-box",
      }}
    >
      {/* VIDEO PLAYER */}
      <div
        style={{
          maxWidth: "900px",
          width: "100%",
          display: "flex",
          justifyContent: "center",
          margin: "0 auto",
        }}
      >
        <VideoPlayer
          url="https://www.youtube.com/watch?v=Lih7_P_hdNg&t=787s"
        />
      </div>

      {/* SECTION TEXT */}
      <div
        style={{
          maxWidth: "900px",
          width: "100%",
          background: "#222",
          padding: "20px",
          borderRadius: "10px",
          minHeight: "400px",
          whiteSpace: "pre-wrap",
          lineHeight: "1.6",
          overflowY: "auto",
          boxSizing: "border-box",
        }}
      >
        {sections[selectedIndex] ? (
          <>
            <h2 style={{ marginBottom: "10px" }}>
              Section {sections[selectedIndex].number}
            </h2>
            <p>{sections[selectedIndex].text}</p>
          </>
        ) : (
          <p style={{ opacity: 0.7 }}>Loading sections...</p>
        )}
      </div>

      {/* AUDIO PLAYER UNDER TEXT */}
      {sections[selectedIndex] && (
        <div
          style={{
            maxWidth: "900px",
            width: "100%",
            display: "flex",
            justifyContent: "center",
            margin: "0px auto",
          }}
        >
          <audio
            key={sections[selectedIndex].number} // <-- this forces reload
            controls
            style={{ width: "100%" }}
          >
            <source
              src={getAudioUrl(sections[selectedIndex].number)}
              type="audio/mp4"
            />
            Your browser does not support the audio element.
          </audio>
        </div>
      )}

      {/* SECTION BUTTONS */}
      <div
        style={{
          maxWidth: "900px",
          width: "100%",
          display: "grid",
          gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))",
          gap: "12px",
          justifyItems: "center",
          margin: "0 auto",
        }}
      >
        {sections.map((section, i) => (
          <button
            key={i}
            onClick={() => setSelectedIndex(i)}
            style={{
              padding: "12px",
              borderRadius: "10px",
              background: selectedIndex === i ? "#444" : "#222",
              color: "white",
              border: "1px solid #333",
              cursor: "pointer",
              width: "100%",
            }}
          >
            Section {section.number}
          </button>
        ))}
      </div>
    </div>
  );
}

"use client";
import React from "react";

export default function VideoPlayer({ url, width = 640, height = 360 }) {
  // Convert YouTube URLs to embed format
  const convertToEmbed = (u) => {
    if (u.includes("youtu.be/")) {
      const id = u.split("youtu.be/")[1].split("?")[0];
      return `https://www.youtube.com/embed/${id}?controls=1&autoplay=0`;
    }
    const idMatch = u.match(/v=([^&]+)/);
    if (idMatch) {
      const id = idMatch[1];
      return `https://www.youtube.com/embed/${id}?controls=1&autoplay=0`;
    }
    return u;
  };

  const embedUrl = convertToEmbed(url);

  return (
    <div
      style={{
        width: "100%",
        maxWidth: width,
        aspectRatio: `${width} / ${height}`,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <iframe
        width="100%"
        height="100%"
        src={embedUrl}
        title="YouTube Video"
        frameBorder="0"
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
        allowFullScreen
      ></iframe>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import Papa from 'papaparse';

export default function CEFRGrammarPage() {
  const [csvFiles, setCsvFiles] = useState([]);

  useEffect(() => {
    const files = [
      { path: '/cefr/CEFR UNFETTERED.csv', title: 'CEFR UNFETTERED' },
      { path: '/cefr/amadeusgrammar.csv', title: 'Amadeus Grammar' },
    ];

    files.forEach(async (file) => {
      const response = await fetch(file.path);
      const csvText = await response.text();
      const parsed = Papa.parse(csvText, { header: true });
      setCsvFiles((prev) => [...prev, { ...file, data: parsed.data }]);
    });
  }, []);

  const renderTable = (data) => {
    if (!data || data.length === 0) return <p>No data found</p>;

    const headers = Object.keys(data[0]);

    return (
      <table border="1" cellPadding="5" style={{ borderCollapse: 'collapse', marginBottom: '40px' }}>
        <thead>
          <tr>
            {headers.map((header) => (
              <th key={header}>{header}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {data.map((row, idx) => (
            <tr key={idx}>
              {headers.map((header) => (
                <td key={header}>{row[header]}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    );
  };

  return (
    <div style={{ padding: '20px' }}>
      {csvFiles.map((file, idx) => (
        <div key={idx}>
          <h1>{file.title}</h1>
          {renderTable(file.data)}
        </div>
      ))}
    </div>
  );
}

import fs from "fs";
import path from "path";

function getAllJsFiles(dir, root) {
  let files = [];

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isDirectory()) {
      files.push(...getAllJsFiles(fullPath, root));
    } else if (entry.isFile() && entry.name.endsWith(".js")) {
      files.push({
        relativePath: fullPath
          .replace(root, "")
          .replace(/\\/g, "/"),
        content: fs.readFileSync(fullPath, "utf8"),
      });
    }
  }

  return files;
}

export default function Page() {
  const root = process.cwd();

  const srcDir = path.join(root, "src");
  const publicDir = path.join(root, "public");

  const files = [
    ...(fs.existsSync(srcDir) ? getAllJsFiles(srcDir, root) : []),
    ...(fs.existsSync(publicDir) ? getAllJsFiles(publicDir, root) : []),
  ];

  return (
    <main style={{ padding: 24, fontFamily: "monospace" }}>
      <h1>All .js Files (src + public)</h1>

      {files.map((file) => (
        <section
          key={file.relativePath}
          style={{
            marginTop: 32,
            paddingTop: 12,
            borderTop: "2px solid #000",
          }}
        >
          {/* FULL PATH ACROSS THE TOP */}
          <div
            style={{
              fontWeight: "bold",
              fontSize: 13,
              marginBottom: 8,
              color: "#333",
            }}
          >
            {file.relativePath}
          </div>

          <pre
            style={{
              background: "#f5f5f5",
              padding: 16,
              overflowX: "auto",
              fontSize: 12,
            }}
          >
            {file.content}
          </pre>
        </section>
      ))}
    </main>
  );
}

'use client';
import { useEffect, useState } from "react";
import Papa from "papaparse";

export default function MaterialPage() {
  const [data, setData] = useState([]);

  useEffect(() => {
    // Fetch CSV from the public folder
    fetch("/material/materialListClean.csv")
      .then((response) => response.text())
      .then((csvText) => {
        // Parse CSV text
        const parsed = Papa.parse(csvText, { header: true });
        setData(parsed.data);
      })
      .catch((err) => console.error("Error loading CSV:", err));
  }, []);

  return (
    <div style={{ padding: "2rem" }}>
      <h1>Material List</h1>
      {data.length > 0 ? (
        <table border="1" cellPadding="5" cellSpacing="0">
          <thead>
            <tr>
              {Object.keys(data[0]).map((key) => (
                <th key={key}>{key}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {data.map((row, idx) => (
              <tr key={idx}>
                {Object.values(row).map((value, i) => (
                  <td key={i}>{value}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>Loading CSV...</p>
      )}
    </div>
  );
}

