'use client';
import { useEffect, useState } from 'react';

export const dynamic = 'force-static';

export default function Page() {
  const [data, setData] = useState({
    linePics: [],
    vocabPics: [],
    linesCSV: '',
    titlesCSV: '',
    vocabCSV: ''
  });

  useEffect(() => {
    fetch('/segredosecret.json')
      .then(res => res.json())
      .then(setData)
      .catch(err => console.error('Failed to load JSON:', err));
  }, []);

  return (
    <div style={{ padding: 20 }}>
      {/* ---------- LINE PICTURES ---------- */}
      <h1>Line Pictures</h1>
      {data.linePics.map(folder => (
        <div key={folder.title} style={{ marginBottom: 40 }}>
          <h3>{folder.title}</h3>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))',
              gap: 16
            }}
          >
            {folder.images.map(src => (
              <div key={src} style={{ textAlign: 'center' }}>
                <img src={encodeURI(src)} alt={src} style={{ width: 160 }} />
                <div style={{ fontSize: 12, marginTop: 4 }}>
                  {src.split('/').pop()}
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}

      {/* ---------- VOCABULARY PICTURES ---------- */}
      <h1>Vocabulary Pictures</h1>
      {data.vocabPics.map(folder => (
        <div key={folder.title} style={{ marginBottom: 40 }}>
          <h3>{folder.title}</h3>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))',
              gap: 16
            }}
          >
            {folder.images.map(src => (
              <div key={src} style={{ textAlign: 'center' }}>
                <img src={encodeURI(src)} alt={src} style={{ width: 160 }} />
                <div style={{ fontSize: 12, marginTop: 4 }}>
                  {src.split('/').pop()}
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}

      {/* ---------- CSV DATA ---------- */}
      <h1>CSV Data</h1>

      <h3>LinesCSV.csv</h3>
      <pre>{data.linesCSV}</pre>

      <h3>TitlesCSV.csv</h3>
      <pre>{data.titlesCSV}</pre>

      <h3>VocabularyCSV.csv</h3>
      <pre>{data.vocabCSV}</pre>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';

export default function TheKidJsonPage() {
  const [jsonData, setJsonData] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch('/thekid/pdfText/sections.json')
      .then((res) => {
        if (!res.ok) throw new Error('JSON file not found');
        return res.json();
      })
      .then((data) => setJsonData(data))
      .catch((err) => setError(err.message));
  }, []);

  const renderTable = (data) => {
    if (!data) return <p>Loading JSON...</p>;

    if (Array.isArray(data) && data.length > 0 && typeof data[0] === 'object') {
      const headers = Object.keys(data[0]);
      return (
        <table border="1" cellPadding="5" style={{ borderCollapse: 'collapse', marginBottom: '40px' }}>
          <thead>
            <tr>{headers.map((h) => <th key={h}>{h}</th>)}</tr>
          </thead>
          <tbody>
            {data.map((row, idx) => (
              <tr key={idx}>
                {headers.map((h) => <td key={h}>{row[h]}</td>)}
              </tr>
            ))}
          </tbody>
        </table>
      );
    }

    if (typeof data === 'object') {
      return (
        <table border="1" cellPadding="5" style={{ borderCollapse: 'collapse', marginBottom: '40px' }}>
          <thead>
            <tr><th>Key</th><th>Value</th></tr>
          </thead>
          <tbody>
            {Object.entries(data).map(([k, v]) => (
              <tr key={k}>
                <td>{k}</td>
                <td>{typeof v === 'object' ? JSON.stringify(v, null, 2) : v}</td>
              </tr>
            ))}
          </tbody>
        </table>
      );
    }

    return <p>No displayable data</p>;
  };

  return (
    <div style={{ padding: '20px' }}>
      <h1>Charlie Chaplin JSON</h1>
      {error && <p style={{ color: 'red' }}>Error: {error}</p>}
      {renderTable(jsonData)}
    </div>
  );
}

